/**
 * Input Validation and Sanitization for AgentDB Security
 *
 * Provides comprehensive validation to prevent SQL injection and other attacks:
 * - Whitelist-based validation for identifiers (tables, columns, PRAGMA commands)
 * - Input sanitization for user data
 * - Type validation and constraints
 * - Error handling that doesn't leak sensitive information
 */

/**
 * Allowed table names in AgentDB (whitelist)
 */
const ALLOWED_TABLES = new Set([
  'episodes',
  'episode_embeddings',
  'skills',
  'skill_embeddings',
  'causal_edges',
  'causal_experiments',
  'causal_observations',
  'provenance_certificates',
  'reasoning_patterns',
  'pattern_embeddings',
  'rl_sessions',
  'rl_experiences',
  'rl_policies',
  'rl_q_values',
]);

/**
 * Allowed column names by table (whitelist)
 */
const ALLOWED_COLUMNS: Record<string, Set<string>> = {
  episodes: new Set([
    'id', 'ts', 'session_id', 'task', 'input', 'output', 'critique',
    'reward', 'success', 'latency_ms', 'tokens_used', 'tags', 'metadata'
  ]),
  skills: new Set([
    'id', 'ts', 'name', 'description', 'signature', 'code',
    'success_rate', 'uses', 'avg_reward', 'avg_latency_ms', 'tags', 'metadata'
  ]),
  causal_edges: new Set([
    'id', 'ts', 'from_memory_id', 'from_memory_type', 'to_memory_id',
    'to_memory_type', 'similarity', 'uplift', 'confidence', 'sample_size', 'evidence_ids'
  ]),
  // Add more as needed
};

/**
 * Allowed PRAGMA commands (whitelist)
 */
const ALLOWED_PRAGMAS = new Set([
  'journal_mode',
  'synchronous',
  'cache_size',
  'page_size',
  'page_count',
  'user_version',
  'foreign_keys',
  'temp_store',
  'mmap_size',
  'wal_autocheckpoint',
]);

/**
 * Validation error with safe error messages
 */
export class ValidationError extends Error {
  public readonly code: string;
  public readonly field?: string;

  constructor(message: string, code: string = 'VALIDATION_ERROR', field?: string) {
    super(message);
    this.name = 'ValidationError';
    this.code = code;
    this.field = field;
  }

  /**
   * Get safe error message (doesn't leak sensitive info)
   */
  getSafeMessage(): string {
    return `Invalid input: ${this.field || 'unknown field'}`;
  }
}

/**
 * Validate task string (NEW - for MCP tool optimization)
 */
export function validateTaskString(task: unknown, fieldName: string = 'task'): string {
  if (task === null || task === undefined) {
    throw new ValidationError(`${fieldName} is required`, 'MISSING_REQUIRED_FIELD', fieldName);
  }

  if (typeof task !== 'string') {
    throw new ValidationError(`${fieldName} must be a string`, 'INVALID_TYPE', fieldName);
  }

  const trimmed = task.trim();

  if (trimmed.length === 0) {
    throw new ValidationError(`${fieldName} cannot be empty`, 'EMPTY_STRING', fieldName);
  }

  if (trimmed.length > 10000) {
    throw new ValidationError(`${fieldName} exceeds maximum length of 10000 characters`, 'STRING_TOO_LONG', fieldName);
  }

  // Check for potentially malicious patterns
  const suspiciousPatterns = [
    /<script/i,
    /javascript:/i,
    /on\w+\s*=/i, // onclick=, onload=, etc.
    /\x00/, // Null bytes
  ];

  for (const pattern of suspiciousPatterns) {
    if (pattern.test(trimmed)) {
      throw new ValidationError(`${fieldName} contains potentially malicious content`, 'SUSPICIOUS_CONTENT', fieldName);
    }
  }

  return trimmed;
}

/**
 * Validate numeric range (NEW - for MCP tool optimization)
 */
export function validateNumericRange(
  value: unknown,
  fieldName: string,
  min: number,
  max: number
): number {
  if (value === null || value === undefined) {
    throw new ValidationError(`${fieldName} is required`, 'MISSING_REQUIRED_FIELD', fieldName);
  }

  if (typeof value !== 'number' || isNaN(value) || !isFinite(value)) {
    throw new ValidationError(`${fieldName} must be a valid number`, 'INVALID_NUMBER', fieldName);
  }

  if (value < min || value > max) {
    throw new ValidationError(
      `${fieldName} must be between ${min} and ${max} (got ${value})`,
      'OUT_OF_RANGE',
      fieldName
    );
  }

  return value;
}

/**
 * Validate array length (NEW - for MCP tool optimization)
 */
export function validateArrayLength<T>(
  arr: unknown,
  fieldName: string,
  minLength: number,
  maxLength: number
): T[] {
  if (arr === null || arr === undefined) {
    throw new ValidationError(`${fieldName} is required`, 'MISSING_REQUIRED_FIELD', fieldName);
  }

  if (!Array.isArray(arr)) {
    throw new ValidationError(`${fieldName} must be an array`, 'INVALID_ARRAY', fieldName);
  }

  if (arr.length < minLength || arr.length > maxLength) {
    throw new ValidationError(
      `${fieldName} must contain between ${minLength} and ${maxLength} items (got ${arr.length})`,
      'ARRAY_LENGTH_INVALID',
      fieldName
    );
  }

  return arr as T[];
}

/**
 * Validate object (NEW - for MCP tool optimization)
 */
export function validateObject(
  obj: unknown,
  fieldName: string,
  required: boolean = true
): Record<string, any> {
  if (obj === null || obj === undefined) {
    if (required) {
      throw new ValidationError(`${fieldName} is required`, 'MISSING_REQUIRED_FIELD', fieldName);
    }
    return {};
  }

  if (typeof obj !== 'object' || Array.isArray(obj)) {
    throw new ValidationError(`${fieldName} must be an object`, 'INVALID_OBJECT', fieldName);
  }

  return obj as Record<string, any>;
}

/**
 * Validate boolean (NEW - for MCP tool optimization)
 */
export function validateBoolean(
  value: unknown,
  fieldName: string,
  defaultValue?: boolean
): boolean {
  if (value === null || value === undefined) {
    if (defaultValue !== undefined) {
      return defaultValue;
    }
    throw new ValidationError(`${fieldName} is required`, 'MISSING_REQUIRED_FIELD', fieldName);
  }

  if (typeof value !== 'boolean') {
    throw new ValidationError(`${fieldName} must be a boolean`, 'INVALID_BOOLEAN', fieldName);
  }

  return value;
}

/**
 * Validate enum value (NEW - for MCP tool optimization)
 */
export function validateEnum<T extends string>(
  value: unknown,
  fieldName: string,
  allowedValues: readonly T[]
): T {
  if (value === null || value === undefined) {
    throw new ValidationError(`${fieldName} is required`, 'MISSING_REQUIRED_FIELD', fieldName);
  }

  if (typeof value !== 'string') {
    throw new ValidationError(`${fieldName} must be a string`, 'INVALID_TYPE', fieldName);
  }

  if (!allowedValues.includes(value as T)) {
    throw new ValidationError(
      `${fieldName} must be one of: ${allowedValues.join(', ')} (got "${value}")`,
      'INVALID_ENUM_VALUE',
      fieldName
    );
  }

  return value as T;
}

/**
 * Validate table name against whitelist
 */
export function validateTableName(tableName: string): string {
  if (!tableName || typeof tableName !== 'string') {
    throw new ValidationError('Table name must be a non-empty string', 'INVALID_TABLE', 'tableName');
  }

  const sanitized = tableName.trim().toLowerCase();

  if (!ALLOWED_TABLES.has(sanitized)) {
    throw new ValidationError(
      `Invalid table name: ${sanitized}. Allowed tables: ${Array.from(ALLOWED_TABLES).join(', ')}`,
      'INVALID_TABLE',
      'tableName'
    );
  }

  return sanitized;
}

/**
 * Validate column name against whitelist
 */
export function validateColumnName(tableName: string, columnName: string): string {
  if (!columnName || typeof columnName !== 'string') {
    throw new ValidationError('Column name must be a non-empty string', 'INVALID_COLUMN', 'columnName');
  }

  const sanitized = columnName.trim().toLowerCase();
  const validatedTable = validateTableName(tableName);

  const allowedColumns = ALLOWED_COLUMNS[validatedTable];
  if (allowedColumns && !allowedColumns.has(sanitized)) {
    throw new ValidationError(
      `Invalid column name for table ${validatedTable}: ${sanitized}`,
      'INVALID_COLUMN',
      'columnName'
    );
  }

  return sanitized;
}

/**
 * Validate PRAGMA command against whitelist
 */
export function validatePragmaCommand(pragma: string): string {
  if (!pragma || typeof pragma !== 'string') {
    throw new ValidationError('PRAGMA command must be a non-empty string', 'INVALID_PRAGMA', 'pragma');
  }

  // Extract the pragma name (before any = or space)
  const pragmaName = pragma.trim().toLowerCase().split(/[=\s]/)[0];

  if (!ALLOWED_PRAGMAS.has(pragmaName)) {
    throw new ValidationError(
      `Invalid PRAGMA command: ${pragmaName}. Allowed: ${Array.from(ALLOWED_PRAGMAS).join(', ')}`,
      'INVALID_PRAGMA',
      'pragma'
    );
  }

  // Return the full pragma for execution (e.g., "journal_mode = WAL")
  return pragma.trim();
}

/**
 * Validate and sanitize session ID
 */
export function validateSessionId(sessionId: string): string {
  if (!sessionId || typeof sessionId !== 'string') {
    throw new ValidationError('Session ID must be a non-empty string', 'INVALID_SESSION_ID', 'sessionId');
  }

  // Allow alphanumeric, hyphens, underscores (max 255 chars)
  const sanitized = sessionId.trim();

  if (sanitized.length > 255) {
    throw new ValidationError('Session ID exceeds maximum length (255)', 'INVALID_SESSION_ID', 'sessionId');
  }

  if (!/^[a-zA-Z0-9_-]+$/.test(sanitized)) {
    throw new ValidationError(
      'Session ID must contain only alphanumeric characters, hyphens, and underscores',
      'INVALID_SESSION_ID',
      'sessionId'
    );
  }

  return sanitized;
}

/**
 * Validate numeric ID
 */
export function validateId(id: any, fieldName: string = 'id'): number {
  const numId = Number(id);

  if (!Number.isFinite(numId) || numId < 0 || !Number.isInteger(numId)) {
    throw new ValidationError(`${fieldName} must be a non-negative integer`, 'INVALID_ID', fieldName);
  }

  return numId;
}

/**
 * Validate timestamp
 */
export function validateTimestamp(timestamp: any, fieldName: string = 'timestamp'): number {
  const numTs = Number(timestamp);

  if (!Number.isFinite(numTs) || numTs < 0) {
    throw new ValidationError(`${fieldName} must be a non-negative number`, 'INVALID_TIMESTAMP', fieldName);
  }

  // Reasonable timestamp bounds (2000-01-01 to 2100-01-01)
  const MIN_TIMESTAMP = 946684800; // 2000-01-01
  const MAX_TIMESTAMP = 4102444800; // 2100-01-01

  if (numTs < MIN_TIMESTAMP || numTs > MAX_TIMESTAMP) {
    throw new ValidationError(
      `${fieldName} is out of valid range (2000-2100)`,
      'INVALID_TIMESTAMP',
      fieldName
    );
  }

  return numTs;
}

/**
 * Validate reward value (0-1)
 */
export function validateReward(reward: any): number {
  const numReward = Number(reward);

  if (!Number.isFinite(numReward)) {
    throw new ValidationError('Reward must be a number', 'INVALID_REWARD', 'reward');
  }

  if (numReward < 0 || numReward > 1) {
    throw new ValidationError('Reward must be between 0 and 1', 'INVALID_REWARD', 'reward');
  }

  return numReward;
}

/**
 * Validate success flag
 */
export function validateSuccess(success: any): boolean {
  if (typeof success === 'boolean') {
    return success;
  }

  if (typeof success === 'number') {
    return success !== 0;
  }

  if (typeof success === 'string') {
    const lower = success.toLowerCase();
    if (lower === 'true' || lower === '1' || lower === 'yes') return true;
    if (lower === 'false' || lower === '0' || lower === 'no') return false;
  }

  throw new ValidationError('Success must be a boolean value', 'INVALID_BOOLEAN', 'success');
}

/**
 * Sanitize text input (prevent extremely long strings, null bytes, etc.)
 */
export function sanitizeText(text: string, maxLength: number = 100000, fieldName: string = 'text'): string {
  if (typeof text !== 'string') {
    throw new ValidationError(`${fieldName} must be a string`, 'INVALID_TEXT', fieldName);
  }

  // Remove null bytes
  const sanitized = text.replace(/\0/g, '');

  if (sanitized.length > maxLength) {
    throw new ValidationError(
      `${fieldName} exceeds maximum length (${maxLength})`,
      'TEXT_TOO_LONG',
      fieldName
    );
  }

  return sanitized;
}

/**
 * Build safe WHERE clause with parameterized values
 * Returns both the SQL clause and the parameter values
 */
export function buildSafeWhereClause(
  tableName: string,
  conditions: Record<string, any>
): { clause: string; values: any[] } {
  const validatedTable = validateTableName(tableName);

  if (!conditions || typeof conditions !== 'object' || Object.keys(conditions).length === 0) {
    throw new ValidationError('Conditions must be a non-empty object', 'INVALID_CONDITIONS', 'conditions');
  }

  const clauses: string[] = [];
  const values: any[] = [];

  for (const [column, value] of Object.entries(conditions)) {
    const validatedColumn = validateColumnName(validatedTable, column);
    clauses.push(`${validatedColumn} = ?`);
    values.push(value);
  }

  return {
    clause: clauses.join(' AND '),
    values,
  };
}

/**
 * Build safe SET clause for UPDATE statements
 */
export function buildSafeSetClause(
  tableName: string,
  updates: Record<string, any>
): { clause: string; values: any[] } {
  const validatedTable = validateTableName(tableName);

  if (!updates || typeof updates !== 'object' || Object.keys(updates).length === 0) {
    throw new ValidationError('Updates must be a non-empty object', 'INVALID_UPDATES', 'updates');
  }

  const clauses: string[] = [];
  const values: any[] = [];

  for (const [column, value] of Object.entries(updates)) {
    const validatedColumn = validateColumnName(validatedTable, column);
    clauses.push(`${validatedColumn} = ?`);
    values.push(value);
  }

  return {
    clause: clauses.join(', '),
    values,
  };
}

/**
 * Validate JSON data
 */
export function validateJSON(data: any, fieldName: string = 'json'): string {
  try {
    return JSON.stringify(data);
  } catch (error) {
    throw new ValidationError(`${fieldName} is not valid JSON`, 'INVALID_JSON', fieldName);
  }
}

/**
 * Validate array of tags
 */
export function validateTags(tags: any): string[] {
  if (!Array.isArray(tags)) {
    throw new ValidationError('Tags must be an array', 'INVALID_TAGS', 'tags');
  }

  const sanitized = tags.map((tag, i) => {
    if (typeof tag !== 'string') {
      throw new ValidationError(`Tag at index ${i} must be a string`, 'INVALID_TAG', `tags[${i}]`);
    }
    return sanitizeText(tag, 100, `tags[${i}]`);
  });

  return sanitized;
}

/**
 * Safe error handler that doesn't leak sensitive information
 */
export function handleSecurityError(error: any): string {
  if (error instanceof ValidationError) {
    // Safe to return validation errors
    return error.message;
  }

  // For other errors, return generic message and log details internally
  console.error('Security error:', error);
  return 'An error occurred while processing your request. Please check your input and try again.';
}

/**
 * AgentDB v2 Security Validation
 *
 * Comprehensive input validation for RuVector integration:
 * - Vector dimension and value validation (NaN/Infinity prevention)
 * - ID sanitization (path traversal prevention)
 * - Search options validation (bounds checking)
 * - Cypher query parameter validation (injection prevention)
 * - Metadata sanitization (sensitive data protection)
 */

import { ValidationError } from './input-validation.js';

/**
 * Security limits for AgentDB v2
 */
export const SECURITY_LIMITS = {
  MAX_VECTORS: 10_000_000,        // 10M vectors max
  MAX_DIMENSION: 4096,            // Maximum vector dimension
  MAX_BATCH_SIZE: 10_000,         // Batch insert limit
  MAX_K: 10_000,                  // Search result limit
  QUERY_TIMEOUT_MS: 30_000,       // 30s query timeout
  MAX_MEMORY_MB: 16_384,          // 16GB memory limit
  MAX_ID_LENGTH: 256,             // ID string length
  MAX_METADATA_SIZE: 65_536,      // 64KB metadata per vector
  MAX_LABEL_LENGTH: 128,          // Graph node label length
  MAX_PROPERTY_KEY_LENGTH: 128,   // Property key length
  MAX_CYPHER_PARAMS: 100,         // Maximum Cypher parameters
  MIN_DIMENSION: 1,               // Minimum vector dimension
  MIN_K: 1,                       // Minimum search results
  MIN_THRESHOLD: 0.0,             // Minimum similarity threshold
  MAX_THRESHOLD: 1.0,             // Maximum similarity threshold
  MIN_EF_SEARCH: 1,               // Minimum HNSW efSearch
  MAX_EF_SEARCH: 1000,            // Maximum HNSW efSearch
  MIN_EF_CONSTRUCTION: 4,         // Minimum HNSW efConstruction
  MAX_EF_CONSTRUCTION: 500,       // Maximum HNSW efConstruction
  MAX_M: 64,                      // Maximum HNSW M parameter
  MIN_M: 2,                       // Minimum HNSW M parameter
} as const;

/**
 * Validate vector embedding data
 * Prevents NaN, Infinity, and dimension mismatches
 */
export function validateVector(
  embedding: Float32Array | number[],
  expectedDim: number,
  fieldName: string = 'vector'
): void {
  // Validate dimension bounds
  if (expectedDim < SECURITY_LIMITS.MIN_DIMENSION || expectedDim > SECURITY_LIMITS.MAX_DIMENSION) {
    throw new ValidationError(
      `Invalid expected dimension: ${expectedDim} (must be between ${SECURITY_LIMITS.MIN_DIMENSION} and ${SECURITY_LIMITS.MAX_DIMENSION})`,
      'INVALID_DIMENSION',
      fieldName
    );
  }

  // Check if embedding exists
  if (!embedding) {
    throw new ValidationError(
      `${fieldName} is required`,
      'MISSING_VECTOR',
      fieldName
    );
  }

  // Validate dimension match
  if (embedding.length !== expectedDim) {
    throw new ValidationError(
      `Invalid ${fieldName} dimension: expected ${expectedDim}, got ${embedding.length}`,
      'DIMENSION_MISMATCH',
      fieldName
    );
  }

  // Validate each value for NaN and Infinity
  for (let i = 0; i < embedding.length; i++) {
    const value = embedding[i];

    if (!Number.isFinite(value)) {
      throw new ValidationError(
        `Invalid value in ${fieldName} at index ${i}: ${value} (NaN or Infinity not allowed)`,
        'INVALID_VECTOR_VALUE',
        `${fieldName}[${i}]`
      );
    }

    // Optional: Check for extreme values that might indicate errors
    if (Math.abs(value) > 1e10) {
      throw new ValidationError(
        `Extreme value in ${fieldName} at index ${i}: ${value} (magnitude too large)`,
        'EXTREME_VECTOR_VALUE',
        `${fieldName}[${i}]`
      );
    }
  }
}

/**
 * Validate vector ID
 * Prevents path traversal, excessive length, and malicious characters
 */
export function validateVectorId(id: string, fieldName: string = 'id'): string {
  if (typeof id !== 'string') {
    throw new ValidationError(
      `${fieldName} must be a string`,
      'INVALID_ID_TYPE',
      fieldName
    );
  }

  if (id.length === 0) {
    throw new ValidationError(
      `${fieldName} cannot be empty`,
      'EMPTY_ID',
      fieldName
    );
  }

  if (id.length > SECURITY_LIMITS.MAX_ID_LENGTH) {
    throw new ValidationError(
      `${fieldName} exceeds maximum length (${SECURITY_LIMITS.MAX_ID_LENGTH} chars)`,
      'ID_TOO_LONG',
      fieldName
    );
  }

  // Prevent path traversal attacks
  if (id.includes('..') || id.includes('/') || id.includes('\\')) {
    throw new ValidationError(
      `${fieldName} contains invalid path characters (., /, \\)`,
      'PATH_TRAVERSAL_ATTEMPT',
      fieldName
    );
  }

  // Prevent null bytes and control characters
  if (/[\x00-\x1F\x7F]/.test(id)) {
    throw new ValidationError(
      `${fieldName} contains control characters`,
      'INVALID_CHARACTERS',
      fieldName
    );
  }

  // Prevent potential Cypher injection via IDs used in graph queries
  const cypherDangerousChars = /['"`;{}[\]()]/;
  if (cypherDangerousChars.test(id)) {
    throw new ValidationError(
      `${fieldName} contains potentially dangerous characters for graph queries`,
      'DANGEROUS_ID_CHARACTERS',
      fieldName
    );
  }

  return id;
}

/**
 * Validate search options
 * Ensures k, threshold, and other parameters are within safe bounds
 */
export interface SearchOptions {
  k?: number;
  threshold?: number;
  efSearch?: number;
  filter?: Record<string, any>;
  includeMetadata?: boolean;
  includeVectors?: boolean;
}

export function validateSearchOptions(options: SearchOptions): SearchOptions {
  const validated: SearchOptions = {};

  // Validate k parameter
  if (options.k !== undefined) {
    if (!Number.isInteger(options.k)) {
      throw new ValidationError(
        'k must be an integer',
        'INVALID_K_TYPE',
        'k'
      );
    }

    if (options.k < SECURITY_LIMITS.MIN_K || options.k > SECURITY_LIMITS.MAX_K) {
      throw new ValidationError(
        `k must be between ${SECURITY_LIMITS.MIN_K} and ${SECURITY_LIMITS.MAX_K}`,
        'K_OUT_OF_BOUNDS',
        'k'
      );
    }

    validated.k = options.k;
  }

  // Validate threshold parameter
  if (options.threshold !== undefined) {
    if (typeof options.threshold !== 'number') {
      throw new ValidationError(
        'threshold must be a number',
        'INVALID_THRESHOLD_TYPE',
        'threshold'
      );
    }

    if (!Number.isFinite(options.threshold)) {
      throw new ValidationError(
        'threshold must be a finite number',
        'THRESHOLD_NOT_FINITE',
        'threshold'
      );
    }

    if (options.threshold < SECURITY_LIMITS.MIN_THRESHOLD ||
        options.threshold > SECURITY_LIMITS.MAX_THRESHOLD) {
      throw new ValidationError(
        `threshold must be between ${SECURITY_LIMITS.MIN_THRESHOLD} and ${SECURITY_LIMITS.MAX_THRESHOLD}`,
        'THRESHOLD_OUT_OF_BOUNDS',
        'threshold'
      );
    }

    validated.threshold = options.threshold;
  }

  // Validate efSearch parameter (HNSW specific)
  if (options.efSearch !== undefined) {
    if (!Number.isInteger(options.efSearch)) {
      throw new ValidationError(
        'efSearch must be an integer',
        'INVALID_EFSEARCH_TYPE',
        'efSearch'
      );
    }

    if (options.efSearch < SECURITY_LIMITS.MIN_EF_SEARCH ||
        options.efSearch > SECURITY_LIMITS.MAX_EF_SEARCH) {
      throw new ValidationError(
        `efSearch must be between ${SECURITY_LIMITS.MIN_EF_SEARCH} and ${SECURITY_LIMITS.MAX_EF_SEARCH}`,
        'EFSEARCH_OUT_OF_BOUNDS',
        'efSearch'
      );
    }

    validated.efSearch = options.efSearch;
  }

  // Validate filter object
  if (options.filter !== undefined) {
    if (typeof options.filter !== 'object' || options.filter === null) {
      throw new ValidationError(
        'filter must be an object',
        'INVALID_FILTER_TYPE',
        'filter'
      );
    }

    validated.filter = sanitizeMetadata(options.filter);
  }

  // Copy boolean flags
  if (options.includeMetadata !== undefined) {
    validated.includeMetadata = Boolean(options.includeMetadata);
  }

  if (options.includeVectors !== undefined) {
    validated.includeVectors = Boolean(options.includeVectors);
  }

  return validated;
}

/**
 * Validate HNSW index parameters
 */
export interface HNSWParams {
  M?: number;
  efConstruction?: number;
  efSearch?: number;
}

export function validateHNSWParams(params: HNSWParams): HNSWParams {
  const validated: HNSWParams = {};

  if (params.M !== undefined) {
    if (!Number.isInteger(params.M)) {
      throw new ValidationError(
        'M must be an integer',
        'INVALID_M_TYPE',
        'M'
      );
    }

    if (params.M < SECURITY_LIMITS.MIN_M || params.M > SECURITY_LIMITS.MAX_M) {
      throw new ValidationError(
        `M must be between ${SECURITY_LIMITS.MIN_M} and ${SECURITY_LIMITS.MAX_M}`,
        'M_OUT_OF_BOUNDS',
        'M'
      );
    }

    validated.M = params.M;
  }

  if (params.efConstruction !== undefined) {
    if (!Number.isInteger(params.efConstruction)) {
      throw new ValidationError(
        'efConstruction must be an integer',
        'INVALID_EFCONSTRUCTION_TYPE',
        'efConstruction'
      );
    }

    if (params.efConstruction < SECURITY_LIMITS.MIN_EF_CONSTRUCTION ||
        params.efConstruction > SECURITY_LIMITS.MAX_EF_CONSTRUCTION) {
      throw new ValidationError(
        `efConstruction must be between ${SECURITY_LIMITS.MIN_EF_CONSTRUCTION} and ${SECURITY_LIMITS.MAX_EF_CONSTRUCTION}`,
        'EFCONSTRUCTION_OUT_OF_BOUNDS',
        'efConstruction'
      );
    }

    validated.efConstruction = params.efConstruction;
  }

  if (params.efSearch !== undefined) {
    const searchOpts = validateSearchOptions({ efSearch: params.efSearch });
    validated.efSearch = searchOpts.efSearch;
  }

  return validated;
}

/**
 * Sanitize metadata to prevent sensitive data exposure
 * Removes fields that commonly contain secrets or PII
 */
export function sanitizeMetadata(
  metadata: Record<string, any>
): Record<string, any> {
  if (!metadata || typeof metadata !== 'object') {
    return {};
  }

  const sanitized = { ...metadata };

  // List of sensitive field names (case-insensitive)
  const sensitivePatterns = [
    /password/i,
    /secret/i,
    /token/i,
    /key/i,
    /credential/i,
    /api[_-]?key/i,
    /auth/i,
    /private/i,
    /ssn/i,
    /social[_-]?security/i,
    /credit[_-]?card/i,
    /card[_-]?number/i,
    /cvv/i,
    /pin/i,
  ];

  // Check metadata size
  const metadataStr = JSON.stringify(metadata);
  if (metadataStr.length > SECURITY_LIMITS.MAX_METADATA_SIZE) {
    throw new ValidationError(
      `Metadata exceeds maximum size (${SECURITY_LIMITS.MAX_METADATA_SIZE} bytes)`,
      'METADATA_TOO_LARGE',
      'metadata'
    );
  }

  // Remove sensitive fields
  for (const key of Object.keys(sanitized)) {
    if (sensitivePatterns.some(pattern => pattern.test(key))) {
      delete sanitized[key];
      console.warn(`[Security] Removed potentially sensitive metadata field: ${key}`);
    }

    // Validate property key length
    if (key.length > SECURITY_LIMITS.MAX_PROPERTY_KEY_LENGTH) {
      throw new ValidationError(
        `Metadata property key exceeds maximum length: ${key.substring(0, 50)}...`,
        'PROPERTY_KEY_TOO_LONG',
        'metadata'
      );
    }
  }

  return sanitized;
}

/**
 * Validate Cypher query parameters for graph operations
 * Prevents Cypher injection attacks
 */
export function validateCypherParams(
  params: Record<string, any>
): Record<string, any> {
  if (!params || typeof params !== 'object') {
    return {};
  }

  if (Object.keys(params).length > SECURITY_LIMITS.MAX_CYPHER_PARAMS) {
    throw new ValidationError(
      `Too many Cypher parameters (max ${SECURITY_LIMITS.MAX_CYPHER_PARAMS})`,
      'TOO_MANY_PARAMS',
      'cypherParams'
    );
  }

  const validated: Record<string, any> = {};

  for (const [key, value] of Object.entries(params)) {
    // Validate parameter key format (must be alphanumeric + underscore)
    if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(key)) {
      throw new ValidationError(
        `Invalid Cypher parameter name: ${key} (must be alphanumeric with underscores)`,
        'INVALID_PARAM_NAME',
        key
      );
    }

    // Validate string values aren't suspiciously long
    if (typeof value === 'string' && value.length > 10000) {
      throw new ValidationError(
        `Cypher parameter value too long: ${key}`,
        'PARAM_VALUE_TOO_LONG',
        key
      );
    }

    // Prevent null bytes in string parameters
    if (typeof value === 'string' && value.includes('\x00')) {
      throw new ValidationError(
        `Cypher parameter contains null bytes: ${key}`,
        'NULL_BYTE_IN_PARAM',
        key
      );
    }

    validated[key] = value;
  }

  return validated;
}

/**
 * Validate graph node label
 */
export function validateLabel(label: string): string {
  if (typeof label !== 'string') {
    throw new ValidationError(
      'Label must be a string',
      'INVALID_LABEL_TYPE',
      'label'
    );
  }

  if (label.length === 0) {
    throw new ValidationError(
      'Label cannot be empty',
      'EMPTY_LABEL',
      'label'
    );
  }

  if (label.length > SECURITY_LIMITS.MAX_LABEL_LENGTH) {
    throw new ValidationError(
      `Label exceeds maximum length (${SECURITY_LIMITS.MAX_LABEL_LENGTH} chars)`,
      'LABEL_TOO_LONG',
      'label'
    );
  }

  // Label must be alphanumeric + underscore (Cypher safe)
  if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(label)) {
    throw new ValidationError(
      'Label must be alphanumeric with underscores, starting with letter or underscore',
      'INVALID_LABEL_FORMAT',
      'label'
    );
  }

  return label;
}

/**
 * Validate batch size for bulk operations
 */
export function validateBatchSize(batchSize: number): number {
  if (!Number.isInteger(batchSize)) {
    throw new ValidationError(
      'Batch size must be an integer',
      'INVALID_BATCH_SIZE_TYPE',
      'batchSize'
    );
  }

  if (batchSize < 1 || batchSize > SECURITY_LIMITS.MAX_BATCH_SIZE) {
    throw new ValidationError(
      `Batch size must be between 1 and ${SECURITY_LIMITS.MAX_BATCH_SIZE}`,
      'BATCH_SIZE_OUT_OF_BOUNDS',
      'batchSize'
    );
  }

  return batchSize;
}

/**
 * Validate vector count doesn't exceed limits
 */
export function validateVectorCount(count: number): void {
  if (count > SECURITY_LIMITS.MAX_VECTORS) {
    throw new ValidationError(
      `Vector count exceeds maximum (${SECURITY_LIMITS.MAX_VECTORS})`,
      'TOO_MANY_VECTORS',
      'vectorCount'
    );
  }
}

/**
 * Safe logging that doesn't expose vectors or sensitive data
 */
export function safeLog(message: string, data?: any): void {
  if (!data) {
    console.log(message);
    return;
  }

  if (typeof data === 'object') {
    const safe = { ...data };

    // Remove sensitive fields
    delete safe.embedding;
    delete safe.vector;
    delete safe.metadata;
    delete safe.password;
    delete safe.token;
    delete safe.apiKey;

    // Truncate IDs if they're arrays
    if (Array.isArray(safe.ids) && safe.ids.length > 5) {
      safe.ids = `[${safe.ids.length} IDs...]`;
    }

    console.log(message, safe);
  } else {
    console.log(message, data);
  }
}

/**
 * Unit tests for crypto.utils.ts
 * Tests all cryptographic operations for security and correctness
 */

import { describe, it, expect, beforeEach } from 'vitest';
import {
  generateSecureRandom,
  generateSecureRandomHex,
  generateSecureRandomBase64,
  hashPassword,
  verifyPassword,
  generateApiKey,
  hashApiKey,
  verifyApiKey,
  generateSessionId,
  generateJWTSecret,
  constantTimeCompare,
  generateHMAC,
  verifyHMAC,
  sha256,
  generateUUID,
  validatePasswordStrength,
} from '../../../utils/crypto.utils.js';

describe('Crypto Utils', () => {
  describe('generateSecureRandom', () => {
    it('should generate buffer of correct length', () => {
      const buffer = generateSecureRandom(32);
      expect(buffer).toBeInstanceOf(Buffer);
      expect(buffer.length).toBe(32);
    });

    it('should generate unique values', () => {
      const buffer1 = generateSecureRandom(32);
      const buffer2 = generateSecureRandom(32);
      expect(buffer1.equals(buffer2)).toBe(false);
    });

    it('should throw error for length < 16', () => {
      expect(() => generateSecureRandom(15)).toThrow('at least 16 bytes');
    });

    it('should throw error for length > 1024', () => {
      expect(() => generateSecureRandom(1025)).toThrow('too large');
    });
  });

  describe('generateSecureRandomHex', () => {
    it('should generate hex string of correct length', () => {
      const hex = generateSecureRandomHex(32);
      expect(hex).toMatch(/^[0-9a-f]+$/);
      expect(hex.length).toBe(64); // 32 bytes = 64 hex chars
    });

    it('should generate unique values', () => {
      const hex1 = generateSecureRandomHex(32);
      const hex2 = generateSecureRandomHex(32);
      expect(hex1).not.toBe(hex2);
    });
  });

  describe('generateSecureRandomBase64', () => {
    it('should generate base64url string', () => {
      const base64 = generateSecureRandomBase64(32);
      expect(base64).toMatch(/^[A-Za-z0-9_-]+$/);
      expect(base64.length).toBeGreaterThan(0);
    });

    it('should not contain +, /, or = characters', () => {
      const base64 = generateSecureRandomBase64(32);
      expect(base64).not.toMatch(/[+/=]/);
    });
  });

  describe('hashPassword', () => {
    it('should hash password successfully', async () => {
      const password = 'TestPassword123!';
      const hash = await hashPassword(password);

      expect(hash).toBeDefined();
      expect(hash.startsWith('$argon2id$')).toBe(true);
    });

    it('should generate different hashes for same password', async () => {
      const password = 'TestPassword123!';
      const hash1 = await hashPassword(password);
      const hash2 = await hashPassword(password);

      expect(hash1).not.toBe(hash2);
    });

    it('should throw error for password < 8 chars', async () => {
      await expect(hashPassword('short')).rejects.toThrow('at least 8 characters');
    });

    it('should throw error for password > 128 chars', async () => {
      const longPassword = 'a'.repeat(129);
      await expect(hashPassword(longPassword)).rejects.toThrow('exceeds maximum length');
    });

    it('should throw error for non-string password', async () => {
      await expect(hashPassword(null as any)).rejects.toThrow('non-empty string');
    });
  });

  describe('verifyPassword', () => {
    it('should verify correct password', async () => {
      const password = 'TestPassword123!';
      const hash = await hashPassword(password);
      const valid = await verifyPassword(password, hash);

      expect(valid).toBe(true);
    });

    it('should reject incorrect password', async () => {
      const password = 'TestPassword123!';
      const hash = await hashPassword(password);
      const valid = await verifyPassword('WrongPassword', hash);

      expect(valid).toBe(false);
    });

    it('should return false for invalid hash', async () => {
      const valid = await verifyPassword('password', 'invalid-hash');
      expect(valid).toBe(false);
    });

    it('should return false for empty inputs', async () => {
      expect(await verifyPassword('', 'hash')).toBe(false);
      expect(await verifyPassword('password', '')).toBe(false);
    });
  });

  describe('generateApiKey', () => {
    it('should generate live API key', () => {
      const result = generateApiKey('live');

      expect(result.key).toMatch(/^agdb_live_[0-9a-f]{64}$/);
      expect(result.hash).toMatch(/^[0-9a-f]{64}$/);
    });

    it('should generate test API key', () => {
      const result = generateApiKey('test');

      expect(result.key).toMatch(/^agdb_test_[0-9a-f]{64}$/);
      expect(result.hash).toMatch(/^[0-9a-f]{64}$/);
    });

    it('should generate unique keys', () => {
      const result1 = generateApiKey('live');
      const result2 = generateApiKey('live');

      expect(result1.key).not.toBe(result2.key);
      expect(result1.hash).not.toBe(result2.hash);
    });

    it('should default to live environment', () => {
      const result = generateApiKey();
      expect(result.key).toMatch(/^agdb_live_/);
    });
  });

  describe('hashApiKey', () => {
    it('should hash API key consistently', () => {
      const apiKey = 'agdb_live_' + '0'.repeat(64);
      const hash1 = hashApiKey(apiKey);
      const hash2 = hashApiKey(apiKey);

      expect(hash1).toBe(hash2);
      expect(hash1).toMatch(/^[0-9a-f]{64}$/);
    });

    it('should throw error for invalid prefix', () => {
      expect(() => hashApiKey('invalid_key')).toThrow('Invalid API key format');
    });

    it('should throw error for non-string key', () => {
      expect(() => hashApiKey(null as any)).toThrow('non-empty string');
    });
  });

  describe('verifyApiKey', () => {
    it('should verify correct API key', () => {
      const { key, hash } = generateApiKey('live');
      const valid = verifyApiKey(key, hash);

      expect(valid).toBe(true);
    });

    it('should reject incorrect API key', () => {
      const { hash } = generateApiKey('live');
      const wrongKey = generateApiKey('live').key;

      const valid = verifyApiKey(wrongKey, hash);
      expect(valid).toBe(false);
    });

    it('should return false for empty inputs', () => {
      expect(verifyApiKey('', 'hash')).toBe(false);
      expect(verifyApiKey('key', '')).toBe(false);
    });

    it('should return false for invalid key format', () => {
      const valid = verifyApiKey('invalid', '0'.repeat(64));
      expect(valid).toBe(false);
    });
  });

  describe('generateSessionId', () => {
    it('should generate valid session ID', () => {
      const sessionId = generateSessionId();

      expect(sessionId).toMatch(/^[A-Za-z0-9_-]+$/);
      expect(sessionId.length).toBeGreaterThan(0);
    });

    it('should generate unique session IDs', () => {
      const id1 = generateSessionId();
      const id2 = generateSessionId();

      expect(id1).not.toBe(id2);
    });
  });

  describe('generateJWTSecret', () => {
    it('should generate valid JWT secret', () => {
      const secret = generateJWTSecret();

      expect(secret).toMatch(/^[A-Za-z0-9_-]+$/);
      expect(secret.length).toBeGreaterThan(64);
    });

    it('should generate unique secrets', () => {
      const secret1 = generateJWTSecret();
      const secret2 = generateJWTSecret();

      expect(secret1).not.toBe(secret2);
    });
  });

  describe('constantTimeCompare', () => {
    it('should return true for equal strings', () => {
      const str = 'test-string-12345';
      expect(constantTimeCompare(str, str)).toBe(true);
    });

    it('should return false for different strings', () => {
      expect(constantTimeCompare('string1', 'string2')).toBe(false);
    });

    it('should return false for different length strings', () => {
      expect(constantTimeCompare('short', 'longer-string')).toBe(false);
    });

    it('should return false for empty inputs', () => {
      expect(constantTimeCompare('', 'test')).toBe(false);
      expect(constantTimeCompare('test', '')).toBe(false);
    });
  });

  describe('generateHMAC', () => {
    it('should generate HMAC signature', () => {
      const data = 'test data';
      const secret = 'secret-key';
      const hmac = generateHMAC(data, secret);

      expect(hmac).toMatch(/^[0-9a-f]{64}$/);
    });

    it('should be deterministic', () => {
      const data = 'test data';
      const secret = 'secret-key';
      const hmac1 = generateHMAC(data, secret);
      const hmac2 = generateHMAC(data, secret);

      expect(hmac1).toBe(hmac2);
    });

    it('should change with different data', () => {
      const secret = 'secret-key';
      const hmac1 = generateHMAC('data1', secret);
      const hmac2 = generateHMAC('data2', secret);

      expect(hmac1).not.toBe(hmac2);
    });

    it('should change with different secret', () => {
      const data = 'test data';
      const hmac1 = generateHMAC(data, 'secret1');
      const hmac2 = generateHMAC(data, 'secret2');

      expect(hmac1).not.toBe(hmac2);
    });
  });

  describe('verifyHMAC', () => {
    it('should verify correct HMAC', () => {
      const data = 'test data';
      const secret = 'secret-key';
      const hmac = generateHMAC(data, secret);

      expect(verifyHMAC(data, hmac, secret)).toBe(true);
    });

    it('should reject incorrect HMAC', () => {
      const data = 'test data';
      const secret = 'secret-key';
      const wrongHMAC = generateHMAC('wrong data', secret);

      expect(verifyHMAC(data, wrongHMAC, secret)).toBe(false);
    });

    it('should reject with wrong secret', () => {
      const data = 'test data';
      const hmac = generateHMAC(data, 'secret1');

      expect(verifyHMAC(data, hmac, 'secret2')).toBe(false);
    });
  });

  describe('sha256', () => {
    it('should generate SHA-256 hash', () => {
      const data = 'test data';
      const hash = sha256(data);

      expect(hash).toMatch(/^[0-9a-f]{64}$/);
    });

    it('should be deterministic', () => {
      const data = 'test data';
      const hash1 = sha256(data);
      const hash2 = sha256(data);

      expect(hash1).toBe(hash2);
    });

    it('should produce different hashes for different data', () => {
      const hash1 = sha256('data1');
      const hash2 = sha256('data2');

      expect(hash1).not.toBe(hash2);
    });
  });

  describe('generateUUID', () => {
    it('should generate valid UUID v4', () => {
      const uuid = generateUUID();

      expect(uuid).toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/);
    });

    it('should generate unique UUIDs', () => {
      const uuid1 = generateUUID();
      const uuid2 = generateUUID();

      expect(uuid1).not.toBe(uuid2);
    });
  });

  describe('validatePasswordStrength', () => {
    it('should accept strong password', () => {
      const result = validatePasswordStrength('StrongPass123!');

      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
      expect(result.score).toBeGreaterThan(4);
    });

    it('should reject short password', () => {
      const result = validatePasswordStrength('Short1!');

      expect(result.valid).toBe(false);
      expect(result.errors).toContain('Password must be at least 8 characters');
    });

    it('should reject password without numbers', () => {
      const result = validatePasswordStrength('OnlyLetters');

      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    it('should reject password with only numbers', () => {
      const result = validatePasswordStrength('12345678');

      expect(result.valid).toBe(false);
      expect(result.errors).toContain('Password should contain letters');
    });

    it('should detect repeated characters', () => {
      const result = validatePasswordStrength('Passsss111');

      expect(result.errors).toContain('Password contains repeated characters');
    });

    it('should detect sequential characters', () => {
      const result = validatePasswordStrength('Password123');

      expect(result.errors).toContain('Password contains sequential characters');
    });

    it('should return error for empty password', () => {
      const result = validatePasswordStrength('');

      expect(result.valid).toBe(false);
      expect(result.errors).toContain('Password is required');
    });

    it('should give higher score for longer passwords', () => {
      const short = validatePasswordStrength('Pass123!');
      const long = validatePasswordStrength('LongerPassword123!');

      expect(long.score).toBeGreaterThan(short.score);
    });
  });
});
